def drag(x,y,nx,ny):
    browser.call('Input.dispatchMouseEvent',type='mouseMoved',x=x,y=y);browser.call('Input.dispatchMouseEvent',type='mousePressed',x=x,y=y,button='left',clickCount=1)
    for k in range(1,9):browser.call('Input.dispatchMouseEvent',type='mouseMoved',x=x+(nx-x)*k/8,y=y+(ny-y)*k/8,button='left',buttons=1)
    browser.call('Input.dispatchMouseEvent',type='mouseReleased',x=nx,y=ny,button='left',clickCount=1)
